@9 n="nominal_main_group_charge_imbalance" d="Signed main-group octet-balance proxy per atom; groups 1, 2, 13–14 donate and groups 15–17 accept." B=686
def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    weight = 0.0
    for element, fraction in (s.get('composition') or {}).items():
        if fraction is None or fraction <= 0.0:
            continue
        group = (props.get(element) or {}).get('group')
        charge = 0.0
        if group == 1 or group == 2:
            charge = float(group)
        elif group == 13 or group == 14:
            charge = float(group - 10)
