            continue
        if sites[i].get('element') == sites[j].get('element'):
            continue
        if ion[i] is None or ion[j] is None or affinity[i] is None or affinity[j] is None:
            continue
        u = d / (1.5 * (radii[i] + radii[j]))
        w = occ[i] * occ[j] * max(0.0, 1.0 - u * u) ** 2
        cost = min(ion[i] - affinity[j], ion[j] - affinity[i]) - 14.399645478 / max(d, 0.1)
        total += w * cost
        weight += w
    return total / max(weight, 1e-12)
@end
@15 n="homonuclear_short_bond_excess" d="Excess short homonuclear bond-order proxy per occupied atom for electronegative group-14–17 sites; directed contacts are halved." B=1090
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if not (0 <= i < n and 0 <= j < n and 0.0 < d <= 6.0):
            continue
        if occ[i] * occ[j] <= 0.0 or sites[i].get('element') != sites[j].get('element'):
            continue
        p = props.get(sites[i].get('element')) or {}
        group = p.get('group')
        en = p.get('eneg')
        if group is None or en is None or not (14 <= group <= 17) or en < 2.0:
            continue
        ratio = (radii[i] + radii[j]) / d
        if ratio > 1.0:
            order = min(3.0, min(2.0, ratio) ** 6)
            total += occ[i] * occ[j] * (order - 1.0)
    return 0.5 * total / max(sum(occ), 1e-12)
@end
@16 n="covalent_corrected_electron_balance" d="Signed main-group electron surplus per atom after radius-derived covalent bonds reduce the octet demand of electronegative group-14–17 sites." B=1863
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    bonds = s.get('neighbors') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    radii = [max(0.1, (props.get(x.get('element')) or {}).get('covalent_radius_A') or 1.3) for x in sites]
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    total = 0.0
    for i in range(n):
        if occ[i] <= 0.0:
            continue
        p = props.get(sites[i].get('element')) or {}
        group = p.get('group')
        en = p.get('eneg')
        if group is None or en is None:
            continue
        if en < 2.0:
            if group == 1 or group == 2:
                total += occ[i] * group
            elif group == 13 or group == 14:
                total += occ[i] * (group - 10)
            continue
        if not (14 <= group <= 17):
            continue
        bond_sum = 0.0
        for b in bonds:
            if b.get('i', -1) != i:
                continue
            j = b.get('j', -1)
            d = b.get('distance_A') or 0.0
            if not (0 <= j < n and 0.0 < d <= 6.0) or occ[j] <= 0.0:
                continue
            q = props.get(sites[j].get('element')) or {}
            other_group = q.get('group')
            other_en = q.get('eneg')
            if other_group is None or other_en is None or other_en < 2.0:
                continue
            main_group = 14 <= other_group <= 17
            hydrogen = other_group == 1 and q.get('row') == 1
            if not (main_group or hydrogen):
                continue
            radius_sum = radii[i] + radii[j]
            if d <= 1.3 * radius_sum:
                ratio = min(2.0, radius_sum / d)
                bond_sum += occ[j] * min(3.0, ratio ** 6)
        total += occ[i] * (bond_sum - (18.0 - group))
    return total / max(sum(occ), 1e-12)
@end
@17 n="occupied_covalent_packing_fraction" d="Occupied covalent-sphere volume divided by unit-cell volume, a dimensionless packing proxy." B=722
def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    if not sites:
        return 0.0
    props = s.get('element_properties') or {}
    volume = (s.get('lattice') or {}).get('volume_A3') or 0.0
    if volume <= 0.0:
        vpa = s.get('volume_per_atom_A3') or (s.get('basic_structure_statistics') or {}).get('volume_per_atom_A3') or 0.0
        volume = vpa * len(sites)
    if volume <= 0.0:
        return 0.0
    total = 0.0
    for site in sites:
        occ = max(0.0, site.get('occupancy', 1.0) or 0.0)
        radius = max(0.1, (props.get(site.get('element')) or {}).get('covalent_radius_A') or 1.3)
        total += occ * radius ** 3
    return 4.1887902047863905 * total / volume
@end
